#### 综合案例：实现伪 UI 按钮交互

利用 `Draw3dRect` 颜色反转的特性，配合文本绘制 API，可以在 `OnLButtonDown` 事件中模拟按钮的按下反馈。

```cpp
void CMainWindow::OnPaint() {
	CPaintDC dc(this);
	CRect rect(10, 10, 100, 50);
	CBrush brush;

	brush.CreateStockObject(LTGRAY_BRUSH);
	dc.FillRect(&rect, &brush); 

	// 调整 3D 边框偏移
	rect.top++;
	rect.left++;
	dc.Draw3dRect(&rect, RGB(255, 255, 255), RGB(128, 128, 128)); // 凸起效果

	// 设置文字背景模式为透明 (TRANSPARENT)，默认不透明 (OPAQUE) 会覆盖画刷背景
	dc.SetBkMode(TRANSPARENT); 

	// 格式化输出正文：水平居中、垂直居中、单行
	dc.DrawText("Click", &rect, DT_CENTER | DT_VCENTER | DT_SINGLELINE); 
}

void CMainWindow::OnLButtonDown(UINT nFlags, CPoint point) {
	// 判断鼠标点击坐标 point 是否在目标 rect 范围内
	if (rect.PtInRect(point)) {
		CClientDC dc(this); // 此处为示意，实际不建议在 OnLButtonDown 中创建局部静态类成员变量

		// 动画效果：按下边缘反转
		dc.Draw3dRect(&rect, RGB(0, 0, 0), RGB(0, 0, 0)); 
		AfxMessageBox("Clicked!");

		// 动画效果：弹起复原
		dc.Draw3dRect(&rect, RGB(255, 255, 255), RGB(128, 128, 128)); 
	}
}
```
